SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS pharmacy_suppliers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,branch_id INT UNSIGNED NOT NULL,supplier_code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,gstin VARCHAR(20),drug_license_no VARCHAR(100),contact_person VARCHAR(120),mobile VARCHAR(20),email VARCHAR(150),address VARCHAR(255),credit_days INT UNSIGNED DEFAULT 0,opening_balance DECIMAL(12,2) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,created_by INT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(created_by) REFERENCES users(id),INDEX(branch_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharmacy_medicines (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,branch_id INT UNSIGNED NOT NULL,medicine_id INT UNSIGNED NULL,sku VARCHAR(40) NOT NULL UNIQUE,barcode VARCHAR(80) NULL UNIQUE,name VARCHAR(180) NOT NULL,generic_name VARCHAR(180),strength VARCHAR(80),dosage_form VARCHAR(60),pack_size VARCHAR(60),hsn_code VARCHAR(20),gst_rate DECIMAL(5,2) DEFAULT 0,mrp DECIMAL(12,2) DEFAULT 0,purchase_rate DECIMAL(12,2) DEFAULT 0,sale_rate DECIMAL(12,2) DEFAULT 0,reorder_level DECIMAL(12,3) DEFAULT 0,manufacturer VARCHAR(180),schedule_type VARCHAR(30),prescription_required TINYINT(1) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,created_by INT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(medicine_id) REFERENCES medicines(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id),INDEX(name),INDEX(generic_name),INDEX(branch_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharmacy_batches (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,medicine_id INT UNSIGNED NOT NULL,batch_number VARCHAR(80) NOT NULL,expiry_date DATE NOT NULL,manufacture_date DATE NULL,purchase_rate DECIMAL(12,2) DEFAULT 0,mrp DECIMAL(12,2) DEFAULT 0,sale_rate DECIMAL(12,2) DEFAULT 0,quantity DECIMAL(12,3) DEFAULT 0,reserved_quantity DECIMAL(12,3) DEFAULT 0,supplier_id INT UNSIGNED NULL,purchase_invoice_no VARCHAR(80),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(medicine_id) REFERENCES pharmacy_medicines(id),FOREIGN KEY(supplier_id) REFERENCES pharmacy_suppliers(id),UNIQUE(medicine_id,batch_number),INDEX(expiry_date),INDEX(medicine_id,quantity)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharmacy_stock_ledger (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,branch_id INT UNSIGNED NOT NULL,medicine_id INT UNSIGNED NOT NULL,batch_id INT UNSIGNED NULL,movement_type ENUM('OPENING','PURCHASE','SALE','SALE_RETURN','PURCHASE_RETURN','ADJUSTMENT','DAMAGE','EXPIRED','TRANSFER_IN','TRANSFER_OUT') NOT NULL,reference_type VARCHAR(40),reference_id BIGINT UNSIGNED,quantity DECIMAL(12,3) NOT NULL,balance_after DECIMAL(12,3) NOT NULL,unit_cost DECIMAL(12,2) DEFAULT 0,reason VARCHAR(255),created_by INT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(medicine_id) REFERENCES pharmacy_medicines(id),FOREIGN KEY(batch_id) REFERENCES pharmacy_batches(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id),INDEX(medicine_id,created_at),INDEX(reference_type,reference_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharmacy_purchases (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,branch_id INT UNSIGNED NOT NULL,purchase_number VARCHAR(30) NOT NULL UNIQUE,supplier_id INT UNSIGNED NOT NULL,supplier_invoice_no VARCHAR(80),purchase_date DATE NOT NULL,gross_amount DECIMAL(12,2) DEFAULT 0,discount_amount DECIMAL(12,2) DEFAULT 0,tax_amount DECIMAL(12,2) DEFAULT 0,net_amount DECIMAL(12,2) DEFAULT 0,paid_amount DECIMAL(12,2) DEFAULT 0,due_amount DECIMAL(12,2) DEFAULT 0,status ENUM('DRAFT','POSTED','CANCELLED') DEFAULT 'DRAFT',notes VARCHAR(500),created_by INT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(supplier_id) REFERENCES pharmacy_suppliers(id),FOREIGN KEY(created_by) REFERENCES users(id),INDEX(purchase_date),INDEX(supplier_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharmacy_purchase_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,purchase_id BIGINT UNSIGNED NOT NULL,medicine_id INT UNSIGNED NOT NULL,batch_id INT UNSIGNED NOT NULL,quantity DECIMAL(12,3) NOT NULL,free_quantity DECIMAL(12,3) DEFAULT 0,purchase_rate DECIMAL(12,2) NOT NULL,mrp DECIMAL(12,2) NOT NULL,gst_rate DECIMAL(5,2) DEFAULT 0,tax_amount DECIMAL(12,2) DEFAULT 0,amount DECIMAL(12,2) NOT NULL,FOREIGN KEY(purchase_id) REFERENCES pharmacy_purchases(id) ON DELETE CASCADE,FOREIGN KEY(medicine_id) REFERENCES pharmacy_medicines(id),FOREIGN KEY(batch_id) REFERENCES pharmacy_batches(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharmacy_sales (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,branch_id INT UNSIGNED NOT NULL,sale_number VARCHAR(30) NOT NULL UNIQUE,patient_id INT UNSIGNED NULL,customer_name VARCHAR(180),customer_mobile VARCHAR(20),prescription_id INT UNSIGNED NULL,sale_date DATETIME DEFAULT CURRENT_TIMESTAMP,gross_amount DECIMAL(12,2) DEFAULT 0,discount_amount DECIMAL(12,2) DEFAULT 0,tax_amount DECIMAL(12,2) DEFAULT 0,net_amount DECIMAL(12,2) DEFAULT 0,paid_amount DECIMAL(12,2) DEFAULT 0,due_amount DECIMAL(12,2) DEFAULT 0,status ENUM('DRAFT','PAID','PARTIAL','CREDIT','CANCELLED','RETURNED') DEFAULT 'DRAFT',payment_method ENUM('CASH','UPI','CARD','CREDIT','MIXED') NULL,reference_number VARCHAR(100),notes VARCHAR(500),created_by INT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE SET NULL,FOREIGN KEY(prescription_id) REFERENCES prescriptions(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id),INDEX(sale_date),INDEX(patient_id),INDEX(customer_mobile)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharmacy_sale_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sale_id BIGINT UNSIGNED NOT NULL,medicine_id INT UNSIGNED NOT NULL,batch_id INT UNSIGNED NOT NULL,medicine_name_snapshot VARCHAR(180) NOT NULL,batch_number_snapshot VARCHAR(80) NOT NULL,expiry_date_snapshot DATE NOT NULL,quantity DECIMAL(12,3) NOT NULL,unit_price DECIMAL(12,2) NOT NULL,discount_amount DECIMAL(12,2) DEFAULT 0,gst_rate DECIMAL(5,2) DEFAULT 0,tax_amount DECIMAL(12,2) DEFAULT 0,line_total DECIMAL(12,2) DEFAULT 0,FOREIGN KEY(sale_id) REFERENCES pharmacy_sales(id) ON DELETE CASCADE,FOREIGN KEY(medicine_id) REFERENCES pharmacy_medicines(id),FOREIGN KEY(batch_id) REFERENCES pharmacy_batches(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharmacy_payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sale_id BIGINT UNSIGNED NOT NULL,receipt_number VARCHAR(30) NOT NULL UNIQUE,amount DECIMAL(12,2) NOT NULL,method ENUM('CASH','UPI','CARD') NOT NULL,reference_number VARCHAR(100),paid_by INT UNSIGNED NOT NULL,paid_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(sale_id) REFERENCES pharmacy_sales(id),FOREIGN KEY(paid_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharmacy_accounts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,branch_id INT UNSIGNED NOT NULL,code VARCHAR(30) NOT NULL,name VARCHAR(150) NOT NULL,account_type ENUM('ASSET','LIABILITY','EQUITY','INCOME','EXPENSE') NOT NULL,parent_id INT UNSIGNED NULL,opening_balance DECIMAL(12,2) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(parent_id) REFERENCES pharmacy_accounts(id) ON DELETE SET NULL,UNIQUE(branch_id,code)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharmacy_journals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,branch_id INT UNSIGNED NOT NULL,journal_number VARCHAR(30) NOT NULL UNIQUE,journal_date DATE NOT NULL,reference_type VARCHAR(40),reference_id BIGINT UNSIGNED,narration VARCHAR(500),created_by INT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharmacy_journal_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,journal_id BIGINT UNSIGNED NOT NULL,account_id INT UNSIGNED NOT NULL,debit DECIMAL(12,2) DEFAULT 0,credit DECIMAL(12,2) DEFAULT 0,FOREIGN KEY(journal_id) REFERENCES pharmacy_journals(id) ON DELETE CASCADE,FOREIGN KEY(account_id) REFERENCES pharmacy_accounts(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharmacy_expenses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,branch_id INT UNSIGNED NOT NULL,expense_number VARCHAR(30) NOT NULL UNIQUE,expense_date DATE NOT NULL,category VARCHAR(100) NOT NULL,description VARCHAR(255),amount DECIMAL(12,2) NOT NULL,payment_method ENUM('CASH','UPI','CARD','BANK') DEFAULT 'CASH',reference_number VARCHAR(100),created_by INT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharmacy_stock_adjustments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,branch_id INT UNSIGNED NOT NULL,adjustment_number VARCHAR(30) NOT NULL UNIQUE,medicine_id INT UNSIGNED NOT NULL,batch_id INT UNSIGNED NULL,quantity_change DECIMAL(12,3) NOT NULL,reason VARCHAR(255) NOT NULL,created_by INT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(medicine_id) REFERENCES pharmacy_medicines(id),FOREIGN KEY(batch_id) REFERENCES pharmacy_batches(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
INSERT INTO roles(code,name) VALUES('PHARMACY_STAFF','Pharmacy / Medical Store Staff'),('ACCOUNTANT','Accounts / ERP Staff') ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO permissions(code,description) VALUES('pharmacy.view','View pharmacy ERP'),('pharmacy.pos','Pharmacy POS billing'),('pharmacy.inventory','Medicine and stock management'),('pharmacy.purchase','Purchases and suppliers'),('pharmacy.return','Returns and stock adjustments'),('pharmacy.accounts','Pharmacy accounting'),('pharmacy.reports','Pharmacy reports') ON DUPLICATE KEY UPDATE description=VALUES(description);
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='SUPER_ADMIN' ON DUPLICATE KEY UPDATE role_id=role_id;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code IN('pharmacy.view','pharmacy.pos','pharmacy.inventory','pharmacy.purchase','pharmacy.return','pharmacy.reports') WHERE r.code='PHARMACY_STAFF' ON DUPLICATE KEY UPDATE role_id=role_id;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code IN('pharmacy.view','pharmacy.accounts','pharmacy.reports') WHERE r.code='ACCOUNTANT' ON DUPLICATE KEY UPDATE role_id=role_id;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code IN('pharmacy.view','pharmacy.pos','pharmacy.inventory','pharmacy.purchase','pharmacy.return','pharmacy.reports') WHERE r.code='ADMIN' ON DUPLICATE KEY UPDATE role_id=role_id;
INSERT INTO pharmacy_accounts(branch_id,code,name,account_type) SELECT id,'1100','Pharmacy Cash / Bank','ASSET' FROM branches WHERE is_active=1 ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO pharmacy_accounts(branch_id,code,name,account_type) SELECT id,'1200','Pharmacy Inventory','ASSET' FROM branches WHERE is_active=1 ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO pharmacy_accounts(branch_id,code,name,account_type) SELECT id,'2100','Supplier Payables','LIABILITY' FROM branches WHERE is_active=1 ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO pharmacy_accounts(branch_id,code,name,account_type) SELECT id,'4100','Pharmacy Sales','INCOME' FROM branches WHERE is_active=1 ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO pharmacy_accounts(branch_id,code,name,account_type) SELECT id,'5100','Pharmacy Purchase / COGS','EXPENSE' FROM branches WHERE is_active=1 ON DUPLICATE KEY UPDATE name=VALUES(name);
INSERT INTO pharmacy_accounts(branch_id,code,name,account_type) SELECT id,'5200','Pharmacy Operating Expenses','EXPENSE' FROM branches WHERE is_active=1 ON DUPLICATE KEY UPDATE name=VALUES(name);